impl CodeSuggestion { # [doc = " Returns the assembled code suggestions, whether they should be shown with an underline"] # [doc = " and whether the substitution only differs in capitalization."] pub fn splice_lines (& self , sm : & SourceMap ,) -> Vec < (String , Vec < TrimmedSubstitutionPart > , Vec < Vec < SubstitutionHighlight > > , ConfusionType ,) > { use rustc_span :: { CharPos , Pos } ; # [doc = " Extracts a substring from the provided `line_opt` based on the specified low and high"] # [doc = " indices, appends it to the given buffer `buf`, and returns the count of newline"] # [doc = " characters in the substring for accurate highlighting. If `line_opt` is `None`, a"] # [doc = " newline character is appended to the buffer, and 0 is returned."] # [doc = ""] # [doc = " ## Returns"] # [doc = ""] # [doc = " The count of newline characters in the extracted substring."] fn push_trailing (buf : & mut String , line_opt : Option < & Cow < '_ , str > > , lo : & Loc , hi_opt : Option < & Loc > ,) -> usize { let mut line_count = 0 ; let (lo , hi_opt) = (lo . col . to_usize () , hi_opt . map (| hi | hi . col . to_usize ())) ; if let Some (line) = line_opt { if let Some (lo) = line . char_indices () . map (| (i , _) | i) . nth (lo) { let hi_opt = hi_opt . and_then (| hi | line . char_indices () . map (| (i , _) | i) . nth (hi)) ; match hi_opt { Some (hi) if hi > lo => { line_count = line [lo .. hi] . matches ('\n') . count () ; buf . push_str (& line [lo .. hi]) } Some (_) => { } None => { line_count = line [lo ..] . matches ('\n') . count () ; buf . push_str (& line [lo ..]) } } } if hi_opt . is_none () { buf . push ('\n') ; } } line_count } assert ! (! self . substitutions . is_empty ()) ; self . substitutions . iter () . filter (| subst | { let invalid = subst . parts . iter () . any (| item | sm . is_valid_span (item . span) . is_err ()) ; if invalid { debug ! ("splice_lines: suggestion contains an invalid span: {:?}" , subst) ; } ! invalid }) . cloned () . filter_map (| mut substitution | { substitution . parts . sort_by_key (| part | part . span . lo ()) ; let lo = substitution . parts . iter () . map (| part | part . span . lo ()) . min () ? ; let hi = substitution . parts . iter () . map (| part | part . span . hi ()) . max () ? ; let bounding_span = Span :: with_root_ctxt (lo , hi) ; let lines = sm . span_to_lines (bounding_span) . ok () ? ; assert ! (! lines . lines . is_empty () || bounding_span . is_dummy ()) ; if ! sm . ensure_source_file_source_present (& lines . file) { return None ; } let mut highlights = vec ! [] ; let sf = & lines . file ; let mut prev_hi = sm . lookup_char_pos (bounding_span . lo ()) ; prev_hi . col = CharPos :: from_usize (0) ; let mut prev_line = lines . lines . get (0) . and_then (| line0 | sf . get_line (line0 . line_index)) ; let mut buf = String :: new () ; let mut line_highlight = vec ! [] ; let mut acc = 0 ; let mut confusion_type = ConfusionType :: None ; let trimmed_parts = substitution . parts . into_iter () . map (| part | part . trim_trivial_replacements (sm)) . collect :: < Vec < _ > > () ; for part in & trimmed_parts { let part_confusion = detect_confusion_type (sm , & part . snippet , part . span) ; confusion_type = confusion_type . combine (part_confusion) ; let cur_lo = sm . lookup_char_pos (part . span . lo ()) ; if prev_hi . line == cur_lo . line { let mut count = push_trailing (& mut buf , prev_line . as_ref () , & prev_hi , Some (& cur_lo)) ; while count > 0 { highlights . push (std :: mem :: take (& mut line_highlight)) ; acc = 0 ; count -= 1 ; } } else { acc = 0 ; highlights . push (std :: mem :: take (& mut line_highlight)) ; let mut count = push_trailing (& mut buf , prev_line . as_ref () , & prev_hi , None) ; while count > 0 { highlights . push (std :: mem :: take (& mut line_highlight)) ; count -= 1 ; } for idx in prev_hi . line .. (cur_lo . line - 1) { if let Some (line) = sf . get_line (idx) { buf . push_str (line . as_ref ()) ; buf . push ('\n') ; highlights . push (std :: mem :: take (& mut line_highlight)) ; } } if let Some (cur_line) = sf . get_line (cur_lo . line - 1) { let end = match cur_line . char_indices () . nth (cur_lo . col . to_usize ()) { Some ((i , _)) => i , None => cur_line . len () , } ; buf . push_str (& cur_line [.. end]) ; } } let len : isize = part . snippet . split ('\n') . next () . unwrap_or (& part . snippet) . chars () . map (| c | match c { '\t' => 4 , _ => 1 , }) . sum () ; if ! is_different (sm , & part . snippet , part . span) { } else { line_highlight . push (SubstitutionHighlight { start : (cur_lo . col . 0 as isize + acc) as usize , end : (cur_lo . col . 0 as isize + acc + len) as usize , }) ; } buf . push_str (& part . snippet) ; let cur_hi = sm . lookup_char_pos (part . span . hi ()) ; acc += len - (cur_hi . col . 0 as isize - cur_lo . col . 0 as isize) ; prev_hi = cur_hi ; prev_line = sf . get_line (prev_hi . line - 1) ; for line in part . snippet . split ('\n') . skip (1) { acc = 0 ; highlights . push (std :: mem :: take (& mut line_highlight)) ; let end : usize = line . chars () . map (| c | match c { '\t' => 4 , _ => 1 , }) . sum () ; line_highlight . push (SubstitutionHighlight { start : 0 , end }) ; } } highlights . push (std :: mem :: take (& mut line_highlight)) ; if ! buf . ends_with ('\n') { push_trailing (& mut buf , prev_line . as_ref () , & prev_hi , None) ; } while buf . ends_with ('\n') { buf . pop () ; } if highlights . iter () . all (| parts | parts . is_empty ()) { None } else { Some ((buf , trimmed_parts , highlights , confusion_type)) } }) . collect () } }